  ('3344c8b5-f913-5f7d-9a33-1840b9ba5a0d', '247d0734-b4cd-58dc-8cde-ee043d8582b2', 'EXT-REUT-002', 'Apple reports record Q3 revenue of $95.8 billion', 'https://example.com/cnbcindonesia/2', 'Jane Smith', '2026-06-14 06:01:15+00:00', 'Apple Inc. posted a new quarterly revenue record driven by strong iPhone and Services growth. AAPL rose 3% in after-hours trading as margins beat estimates.', '60adbec2d99aaf8d21a23978b01add6cad3c79735053784e450b46fa52c35c04', 'en', 'analyzed'),
